-- Owner-uploaded images (F4), so far only server/network backgrounds.
--
-- The file itself lives on disk at UPLOAD_DIR/<id>.<ext> (ext from mime), the
-- name generated by the backend, never taken from the upload. This row is the
-- only thing that says whether it may be served: the backend's GET /uploads/:id
-- streams it publicly only once an admin has set status = 'approved'. Rejecting
-- deletes the file but keeps the row as the moderation record.
--
-- The target (exactly one of server_group_id / server_id) is what the owner
-- uploaded it FOR: it tells the admin queue where it will appear, and limits
-- which customisation may later use it. server_id is the raw servers.id the
-- owner was managing, never the family root (same rule as every user-content
-- table, see CLAUDE.md "Server Identity"); reads resolve it through
-- server_canonical.
--
-- uploader_id / reviewed_by are SET NULL on account deletion rather than
-- cascading: a cascade would orphan the file on disk, and an approved image
-- may be the background a co-owner is still using.
--
-- Same explicit-GRANT rule as every user-content migration.

create table if not exists uploaded_images (
    id              uuid primary key,
    uploader_id     bigint references users (id) on delete set null,
    server_group_id integer references server_groups (id) on delete cascade,
    -- The raw servers.id the owner was managing, never the family root.
    server_id       integer references servers (id) on delete cascade,
    kind            text not null check (kind in ('background')),
    mime            text not null check (mime in ('image/png', 'image/jpeg', 'image/webp')),
    bytes           integer not null check (bytes > 0),
    width           integer not null check (width > 0),
    height          integer not null check (height > 0),
    status          text not null default 'pending' check (status in ('pending', 'approved', 'rejected')),
    reviewed_by     bigint references users (id) on delete set null,
    reviewed_at     timestamptz,
    reject_reason   text check (reject_reason is null or char_length(reject_reason) <= 500),
    created_at      timestamptz not null default now(),
    constraint uploaded_images_exactly_one_target check (num_nonnulls(server_group_id, server_id) = 1)
);

-- The admin queue reads by status, newest first.
create index if not exists uploaded_images_status_idx on uploaded_images (status, created_at desc);
-- The owner panel lists a target's images.
create index if not exists uploaded_images_server_group_id_idx on uploaded_images (server_group_id) where server_group_id is not null;
create index if not exists uploaded_images_server_id_idx on uploaded_images (server_id) where server_id is not null;
-- The per-user pending cap.
create index if not exists uploaded_images_uploader_pending_idx on uploaded_images (uploader_id) where status = 'pending';

grant select, insert, update, delete on uploaded_images to app_user_rw;
